(()=>{window.playConfirmSound=function(){if(window._soundEffects!==!1)try{var e=new(window.AudioContext||window.webkitAudioContext),n=e.createOscillator(),t=e.createGain();n.connect(t),t.connect(e.destination),n.frequency.value=1200,n.type="sine",t.gain.setValueAtTime(.15,e.currentTime),t.gain.exponentialRampToValueAtTime(.001,e.currentTime+.12),n.start(e.currentTime),n.stop(e.currentTime+.12)}catch(i){}};})();
